def init_mapping(self):
    import heapq
    from collections import defaultdict

    N = self.num_qubits

    # ---- 1. Build weighted logical interaction graph from self.access ----
    logical_adj = defaultdict(lambda: defaultdict(float))
    logical_qubits = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            logical_adj[a][b] += 1.0
            logical_adj[b][a] += 1.0
            logical_qubits.add(a)
            logical_qubits.add(b)

    # ---- 2. Build physical graph ----
    phys_adj = defaultdict(set)
    for (u, v) in self.backend_connections:
        if 0 <= u < N and 0 <= v < N and u != v:
            phys_adj[u].add(v)
            phys_adj[v].add(u)

    # ---- 3. Weighted k-core peeling (returns coreness dict) ----
    def weighted_coreness(nodes, adj_weighted):
        # adj_weighted: node -> {neighbor: weight}
        coreness = {}
        deg = {n: sum(adj_weighted[n].values()) for n in nodes}
        active = set(nodes)
        # min-heap of (degree, node); lazy deletion
        heap = [(deg[n], n) for n in nodes]
        heapq.heapify(heap)
        current_core = 0.0
        while active:
            while heap and (heap[0][1] not in active or heap[0][0] != deg[heap[0][1]]):
                heapq.heappop(heap)
            if not heap:
                break
            d, node = heapq.heappop(heap)
            if node not in active:
                continue
            current_core = max(current_core, d)
            coreness[node] = current_core
            active.discard(node)
            for nb, w in adj_weighted[node].items():
                if nb in active:
                    deg[nb] -= w
                    heapq.heappush(heap, (deg[nb], nb))
        return coreness

    # Unweighted coreness for physical graph
    def unweighted_coreness(nodes, adj_set):
        coreness = {}
        deg = {n: len(adj_set[n]) for n in nodes}
        active = set(nodes)
        heap = [(deg[n], n) for n in nodes]
        heapq.heapify(heap)
        current_core = 0
        while active:
            while heap and (heap[0][1] not in active or heap[0][0] != deg[heap[0][1]]):
                heapq.heappop(heap)
            if not heap:
                break
            d, node = heapq.heappop(heap)
            if node not in active:
                continue
            current_core = max(current_core, d)
            coreness[node] = current_core
            active.discard(node)
            for nb in adj_set[node]:
                if nb in active:
                    deg[nb] -= 1
                    heapq.heappush(heap, (deg[nb], nb))
        return coreness

    log_core = weighted_coreness(list(logical_qubits), logical_adj) if logical_qubits else {}
    phys_nodes = list(range(N))
    phys_core = unweighted_coreness(phys_nodes, phys_adj)

    # ---- 4. Order qubits by (coreness desc, weighted-degree desc) ----
    log_wdeg = {q: sum(logical_adj[q].values()) for q in logical_qubits}
    logical_order = sorted(
        logical_qubits,
        key=lambda q: (-log_core.get(q, 0.0), -log_wdeg.get(q, 0.0), q),
    )
    phys_deg = {p: len(phys_adj[p]) for p in phys_nodes}
    phys_order_base = sorted(
        phys_nodes,
        key=lambda p: (-phys_core.get(p, 0), -phys_deg.get(p, 0), p),
    )

    # ---- 5. Greedy concentric placement ----
    mapping = [None] * N
    reverse = [None] * N
    used_phys = set()
    placed_logical = []  # list of (logical_q, physical_q)

    for lq in logical_order:
        # Compute candidate cost: prefer physical qubits with high coreness
        # AND close to already-placed neighbors of lq in logical graph.
        neighbors_placed = [
            (mapping[nb], w)
            for nb, w in logical_adj[lq].items()
            if mapping[nb] is not None
        ]

        best_phys = None
        best_key = None
        for p in phys_order_base:
            if p in used_phys:
                continue
            if neighbors_placed:
                dist_cost = 0.0
                for (pn, w) in neighbors_placed:
                    dist_cost += w * self.distance_matrix[p][pn]
            else:
                dist_cost = 0.0
            # rank: lower dist_cost first, then higher physical coreness, then higher degree
            key = (
                dist_cost,
                -phys_core.get(p, 0),
                -phys_deg.get(p, 0),
                p,
            )
            if best_key is None or key < best_key:
                best_key = key
                best_phys = p
        if best_phys is None:
            break
        mapping[lq] = best_phys
        reverse[best_phys] = lq
        used_phys.add(best_phys)
        placed_logical.append((lq, best_phys))

    # ---- 6. Identity-style fill for remaining logical/physical ids ----
    remaining_phys = [p for p in range(N) if p not in used_phys]
    rp_iter = iter(remaining_phys)
    for lq in range(N):
        if mapping[lq] is None:
            try:
                p = next(rp_iter)
            except StopIteration:
                break
            mapping[lq] = p
            reverse[p] = lq

    self.mapping_dict = mapping
    self.reverse_mapping_dict = reverse
    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math, random, heapq
    from collections import defaultdict, deque

    N = self.num_qubits
    self.mapping_dict = [None] * N
    self.reverse_mapping_dict = [None] * N

    # ---------- 1. Build weighted logical interaction graph ----------
    weight = defaultdict(float)        # (u,v) with u<v -> weight
    logical_nodes = set()
    for gate_id, qubits in self.access.items():
        if len(qubits) == 2:
            a, b = qubits[0], qubits[1]
            if a == b:
                continue
            u, v = (a, b) if a < b else (b, a)
            weight[(u, v)] += 1.0
            logical_nodes.add(a); logical_nodes.add(b)

    logical_nodes = sorted(logical_nodes)
    if not logical_nodes:
        for q in range(N):
            self.mapping_dict[q] = q
            self.reverse_mapping_dict[q] = q
        assert len(set(self.mapping_dict)) == len(self.mapping_dict)
        return

    adj = defaultdict(lambda: defaultdict(float))
    for (u, v), w in weight.items():
        adj[u][v] += w
        adj[v][u] += w
    deg = {n: sum(adj[n].values()) for n in logical_nodes}
    m2 = sum(deg.values())  # = 2m
    if m2 <= 0:
        m2 = 1.0

    # ---------- 2. Louvain (single-level, repeated passes) ----------
    community = {n: i for i, n in enumerate(logical_nodes)}
    def louvain_pass(nodes, adj_local, deg_local, m2_local):
        comm = {n: n for n in nodes}
        comm_deg = dict(deg_local)
        improved = True
        order = list(nodes)
        rng = random.Random(0xC0FFEE)
        passes = 0
        while improved and passes < 20:
            improved = False
            passes += 1
            rng.shuffle(order)
            for n in order:
                cur = comm[n]
                k_i = deg_local[n]
                # weights to each neighbor community
                w_to_c = defaultdict(float)
                for nb, w in adj_local[n].items():
                    w_to_c[comm[nb]] += w
                # remove n from its community
                comm_deg[cur] -= k_i
                w_to_cur = w_to_c.get(cur, 0.0)
                best_c = cur
                best_gain = 0.0
                for c, k_in in w_to_c.items():
                    gain = k_in - comm_deg[c] * k_i / m2_local
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_c = c
                # default-stay gain reference
                stay_gain = w_to_cur - comm_deg[cur] * k_i / m2_local
                if best_gain <= stay_gain + 1e-12:
                    best_c = cur
                comm[n] = best_c
                comm_deg[best_c] = comm_deg.get(best_c, 0.0) + k_i
                if best_c != cur:
                    improved = True
        return comm

    comm_map = louvain_pass(logical_nodes, adj, deg, m2)
    # normalize community ids
    cid_remap = {}
    communities = defaultdict(list)
    for n in logical_nodes:
        c = comm_map[n]
        if c not in cid_remap:
            cid_remap[c] = len(cid_remap)
        communities[cid_remap[c]].append(n)
    community_list = [communities[i] for i in range(len(communities))]
    K = len(community_list)

    # ---------- 3. Pick K well-separated physical seeds, grow balanced regions ----------
    K_eff = min(K, N)
    # farthest-point sampling using distance_matrix
    dm = self.distance_matrix
    seeds = [0]
    while len(seeds) < K_eff:
        best_node, best_d = -1, -1
        for p in range(N):
            if p in seeds:
                continue
            d_min = min(dm[p][s] for s in seeds)
            if d_min > best_d:
                best_d = d_min
                best_node = p
        if best_node < 0:
            break
        seeds.append(best_node)

    # target region sizes proportional to community sizes
    comm_sizes = [len(c) for c in community_list[:K_eff]]
    total_c = sum(comm_sizes) if sum(comm_sizes) > 0 else 1
    target = [max(1, int(round(s * N / total_c))) for s in comm_sizes]
    # adjust to sum to N
    diff = N - sum(target)
    i = 0
    while diff != 0 and target:
        if diff > 0:
            target[i % len(target)] += 1; diff -= 1
        else:
            if target[i % len(target)] > 1:
                target[i % len(target)] -= 1; diff += 1
        i += 1
        if i > 10 * N:
            break

    # multi-source balanced BFS
    region_of = [-1] * N
    queues = [deque([s]) for s in seeds]
    region_members = [[] for _ in range(K_eff)]
    for r, s in enumerate(seeds):
        region_of[s] = r
        region_members[r].append(s)
    remaining = N - K_eff
    active = True
    while remaining > 0 and active:
        active = False
        for r in range(K_eff):
            if len(region_members[r]) >= target[r]:
                continue
            grew = False
            while queues[r]:
                cur = queues[r].popleft()
                for nb in self.backend[cur]:
                    if region_of[nb] == -1:
                        region_of[nb] = r
                        region_members[r].append(nb)
                        queues[r].append(nb)
                        remaining -= 1
                        grew = True
                        active = True
                        break
                if grew:
                    break
        if not active and remaining > 0:
            # assign leftovers to nearest region
            for p in range(N):
                if region_of[p] == -1:
                    best_r, best_d = 0, float('inf')
                    for r in range(K_eff):
                        for q in region_members[r]:
                            if dm[p][q] < best_d:
                                best_d = dm[p][q]; best_r = r
                    region_of[p] = best_r
                    region_members[best_r].append(p)
                    remaining -= 1
            break

    # ---------- 4. Match communities to regions (Hungarian on size-difference cost) ----------
    try:
        import numpy as np
        from scipy.optimize import linear_sum_assignment
        cost = np.zeros((K_eff, K_eff), dtype=float)
        for i in range(K_eff):
            ci = len(community_list[i])
            for j in range(K_eff):
                rj = len(region_members[j])
                cost[i][j] = abs(ci - rj)
        row_ind, col_ind = linear_sum_assignment(cost)
        match = {int(r): int(c) for r, c in zip(row_ind, col_ind)}
    except Exception:
        # greedy fallback
        match = {}
        used_r = set()
        order = sorted(range(K_eff), key=lambda i: -len(community_list[i]))
        for ci in order:
            best_r, best_d = -1, float('inf')
            for r in range(K_eff):
                if r in used_r:
                    continue
                d = abs(len(community_list[ci]) - len(region_members[r]))
                if d < best_d:
                    best_d = d; best_r = r
            if best_r >= 0:
                match[ci] = best_r; used_r.add(best_r)

    # ---------- 5. Place qubits inside each matched pair ----------
    used_phys = set()

    def intra_weighted_degree(node, members_set):
        return sum(w for nb, w in adj[node].items() if nb in members_set)

    def intra_region_centrality(p, members_set):
        s = 0.0
        for q in members_set:
            if q == p: continue
            d = dm[p][q]
            if d > 0:
                s += 1.0 / d
        return s

    for ci, ri in match.items():
        comm_nodes = community_list[ci]
        comm_set = set(comm_nodes)
        region_nodes = list(region_members[ri])
        # sort logical by descending intra-community weighted degree
        sorted_log = sorted(comm_nodes,
                            key=lambda n: (-intra_weighted_degree(n, comm_set), n))
        region_set = set(region_nodes)
        sorted_phys = sorted(region_nodes,
                             key=lambda p: (-intra_region_centrality(p, region_set), p))
        for L, P in zip(sorted_log, sorted_phys):
            if L < N and self.mapping_dict[L] is None and P not in used_phys:
                self.mapping_dict[L] = P
                self.reverse_mapping_dict[P] = L
                used_phys.add(P)

    # ---------- 6. Fill remaining logical/physical qubits ----------
    free_phys = [p for p in range(N) if p not in used_phys]
    # logical qubits in access not yet placed
    unplaced_log = [L for L in logical_nodes if L < N and self.mapping_dict[L] is None]
    fp_iter = iter(free_phys)
    for L in unplaced_log:
        try:
            P = next(fp_iter)
        except StopIteration:
            break
        self.mapping_dict[L] = P
        self.reverse_mapping_dict[P] = L
        used_phys.add(P)

    # remaining logical ids (not in access, but index < N) and any leftover phys
    free_phys = [p for p in range(N) if p not in used_phys]
    fp_iter = iter(free_phys)
    for L in range(N):
        if self.mapping_dict[L] is None:
            try:
                P = next(fp_iter)
            except StopIteration:
                # identity fallback
                for p in range(N):
                    if p not in used_phys:
                        P = p; break
                else:
                    P = L
            self.mapping_dict[L] = P
            self.reverse_mapping_dict[P] = L
            used_phys.add(P)

    # final safety: if any duplicates due to corner cases, repair via identity
    if len(set(self.mapping_dict)) != len(self.mapping_dict):
        self.mapping_dict = list(range(N))
        self.reverse_mapping_dict = list(range(N))

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)

def init_mapping(self):
    import math
    from collections import defaultdict

    N = self.num_qubits
    self.mapping_dict = [None] * N
    self.reverse_mapping_dict = [None] * N

    try:
        sorted_gate_ids = sorted(self.access.keys())
    except Exception:
        sorted_gate_ids = list(self.access.keys())

    interactions = []
    depth_idx = 0
    logical_qubits = set()
    for gid in sorted_gate_ids:
        qubits = self.access[gid]
        if qubits is None:
            continue
        for q in qubits:
            if isinstance(q, int) and 0 <= q < N:
                logical_qubits.add(q)
        if len(qubits) == 2:
            q1, q2 = qubits[0], qubits[1]
            if q1 == q2:
                continue
            if not (0 <= q1 < N and 0 <= q2 < N):
                continue
            interactions.append((q1, q2, depth_idx))
            depth_idx += 1

    M = len(interactions)
    alpha = 3.0 / max(M, 1)

    interaction_weight = defaultdict(lambda: defaultdict(float))
    for q1, q2, d in interactions:
        w = math.exp(-alpha * d)
        interaction_weight[q1][q2] += w
        interaction_weight[q2][q1] += w

    total_weight = {q: sum(interaction_weight[q].values()) for q in logical_qubits}

    centrality_cache = [
        sum(self.distance_matrix[p][q] for q in range(N)) for p in range(N)
    ]
    max_centrality = max(centrality_cache) if centrality_cache else 1.0
    centrality_norm = max_centrality if max_centrality > 0 else 1.0

    # Physical adjacency (for iterative attachment-growth boundary)
    phys_neighbors = [set() for _ in range(N)]
    try:
        for p in range(N):
            row = self.backend[p] if p < len(self.backend) else []
            for q in row:
                if isinstance(q, int) and 0 <= q < N and q != p:
                    phys_neighbors[p].add(q)
    except Exception:
        pass
    if not any(phys_neighbors):
        try:
            for (a, b) in self.backend_connections:
                if 0 <= a < N and 0 <= b < N and a != b:
                    phys_neighbors[a].add(b)
                    phys_neighbors[b].add(a)
        except Exception:
            pass

    used_physical = [False] * N
    placed_logical = set()
    boundary = set()  # h5: dynamically grown attachment frontier

    LOOKAHEAD_DECAY = 0.35
    CENTRALITY_TIE = 1e-3

    if logical_qubits:
        seed_logical = max(
            logical_qubits,
            key=lambda q: (total_weight.get(q, 0.0), -q),
        )
        seed_phys = None
        seed_score = None
        for p in range(N):
            s = centrality_cache[p]
            if seed_score is None or s < seed_score or (s == seed_score and p < seed_phys):
                seed_score = s
                seed_phys = p
        self.mapping_dict[seed_logical] = seed_phys
        self.reverse_mapping_dict[seed_phys] = seed_logical
        used_physical[seed_phys] = True
        placed_logical.add(seed_logical)
        for nb in phys_neighbors[seed_phys]:
            if not used_physical[nb]:
                boundary.add(nb)

    remaining = set(logical_qubits) - placed_logical

    while remaining:
        # Choose next logical qubit: strongest accumulated weight to placed set
        best_cand = None
        best_cand_weight = -1.0
        best_cand_total = -1.0
        for q in remaining:
            w = 0.0
            nbrs = interaction_weight.get(q, {})
            for nbr, wt in nbrs.items():
                if nbr in placed_logical:
                    w += wt
            tw = total_weight.get(q, 0.0)
            if (w > best_cand_weight) \
               or (w == best_cand_weight and tw > best_cand_total) \
               or (w == best_cand_weight and tw == best_cand_total and (best_cand is None or q < best_cand)):
                best_cand_weight = w
                best_cand_total = tw
                best_cand = q

        if best_cand_weight <= 0.0:
            best_cand = max(remaining, key=lambda q: (total_weight.get(q, 0.0), -q))

        placed_neighbors = [
            (nbr, wt) for nbr, wt in interaction_weight.get(best_cand, {}).items()
            if nbr in placed_logical
        ]
        unplaced_neighbors = [
            (nbr, wt) for nbr, wt in interaction_weight.get(best_cand, {}).items()
            if nbr not in placed_logical and nbr != best_cand
        ]

        # h5: ITERATIVE ATTACHMENT GROWTH — restrict to current boundary,
        # i.e. unused physical qubits adjacent to any already-placed qubit.
        candidates = [p for p in boundary if not used_physical[p]]
        if not candidates:
            # Boundary exhausted (e.g., disconnected backend or first step
            # with no placed neighbors): fall back to any unused qubit so
            # the placement never stalls.
            candidates = [p for p in range(N) if not used_physical[p]]

        best_phys = None
        best_cost = None
        for p in candidates:
            if placed_neighbors:
                d = 0.0
                for nbr, wt in placed_neighbors:
                    d += wt * self.distance_matrix[p][self.mapping_dict[nbr]]
                if unplaced_neighbors:
                    avg_dist_to_placed = 0.0
                    cnt = 0
                    for pl in placed_logical:
                        avg_dist_to_placed += self.distance_matrix[p][self.mapping_dict[pl]]
                        cnt += 1
                    if cnt > 0:
                        avg_dist_to_placed /= cnt
                    d += LOOKAHEAD_DECAY * sum(wt for _, wt in unplaced_neighbors) * avg_dist_to_placed
                cost = d + CENTRALITY_TIE * (centrality_cache[p] / centrality_norm)
            else:
                cost = centrality_cache[p]
            if best_cost is None or cost < best_cost or (cost == best_cost and p < best_phys):
                best_cost = cost
                best_phys = p

        if best_phys is None:
            break

        self.mapping_dict[best_cand] = best_phys
        self.reverse_mapping_dict[best_phys] = best_cand
        used_physical[best_phys] = True
        placed_logical.add(best_cand)
        remaining.discard(best_cand)

        # Grow attachment boundary contiguously from the just-placed qubit
        boundary.discard(best_phys)
        for nb in phys_neighbors[best_phys]:
            if not used_physical[nb]:
                boundary.add(nb)

    # Identity-preferred fallback for any unmapped logical qubits
    for l in range(N):
        if self.mapping_dict[l] is None:
            if l < N and not used_physical[l]:
                self.mapping_dict[l] = l
                self.reverse_mapping_dict[l] = l
                used_physical[l] = True
            else:
                for p in range(N):
                    if not used_physical[p]:
                        self.mapping_dict[l] = p
                        self.reverse_mapping_dict[p] = l
                        used_physical[p] = True
                        break

    assert len(set(self.mapping_dict)) == len(self.mapping_dict)
